import argparse
import csv
import io
import math
import subprocess
from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

matplotlib.rcParams["svg.hashsalt"] = "isothermpp-scientific-figures"


def plot_single(path, x, y, xlabel, ylabel, title):
    fig, axis = plt.subplots(figsize=(7.6, 4.3), layout="constrained")
    axis.plot(x, y, color="#087F82", linewidth=2.3)
    axis.scatter(x[::10], y[::10], color="#DF735F", s=17, zorder=3)
    axis.set(xlabel=xlabel, ylabel=ylabel, title=title)
    axis.grid(True, alpha=0.20)
    axis.spines[["top", "right"]].set_visible(False)
    fig.savefig(path, format="svg", transparent=True,
                metadata={"Date": None})
    plt.close(fig)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("executable", type=Path)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    args.output.mkdir(parents=True, exist_ok=True)
    raw = subprocess.run([str(args.executable.resolve())], check=True,
                         capture_output=True, text=True).stdout
    records = list(csv.DictReader(io.StringIO(raw)))
    columns = ["temperature_k", "uptake", "derivative", "sensitivity_1",
               "sensitivity_2", "sensitivity_3", "sensitivity_4"]
    if len(records) != 81 or list(records[0]) != columns:
        raise ValueError("Unexpected four-stored-parameter Smith C++ CSV format")
    data = {column: [float(row[column]) for row in records] for column in columns}
    if not all(math.isfinite(value) for values in data.values() for value in values):
        raise ValueError("Non-finite Smith C++ model data")
    (args.output / "smith_data.csv").write_text(raw, encoding="utf-8")
    temperature = data["temperature_k"]
    xlabel = r"Absolute temperature, $T$ (K)"
    plot_single(args.output / "smith_curve.svg", temperature, data["uptake"],
                xlabel, r"Equilibrium moisture, $q_e$", "Modified Smith temperature section")
    plot_single(args.output / "smith_derivative.svg", temperature, data["derivative"],
                xlabel, r"$\mathrm{d}q_e/\mathrm{d}T$", "Smith — temperature derivative")
    fig, axis = plt.subplots(figsize=(7.6, 4.3), layout="constrained")
    for number, label in enumerate((r"$\lambda_A$", r"$\lambda_B$",
                                    r"$\lambda_C$", r"$\lambda_{a_w}$"), 1):
        axis.plot(temperature, data[f"sensitivity_{number}"],
                  label=label, linewidth=2.2)
    axis.set(xlabel=xlabel, ylabel=r"Scaled sensitivity, $\lambda_i$",
             title="Smith — numerical parameter sensitivities")
    # The highest sensitivity is horizontal near the upper-right legend.
    # Lower only this legend slightly, leaving the plotted data unchanged.
    axis.legend(frameon=False, loc="upper right", bbox_to_anchor=(1.0, 0.94))
    axis.grid(True, alpha=0.20)
    axis.spines[["top", "right"]].set_visible(False)
    fig.savefig(args.output / "smith_sensitivity.svg", format="svg",
                transparent=True, metadata={"Date": None})
    plt.close(fig)


if __name__ == "__main__":
    main()
